"use client";

/**
 * QR-and-poll payment: issue an invoice, show a code the user scans in
 * their banking app, wait for the provider to confirm.
 *
 * Four states: preparing the invoice, waiting for payment, paid, and
 * failed. Polling stops at `timeoutMs` with a "still waiting?" message
 * and a retry, rather than spinning forever.
 *
 * Provider work happens server-side through `@/actions/payment`: the
 * browser never sees provider credentials, never says who is paying —
 * that comes from the session — and never grants anything. A poll that
 * sees the invoice paid has already granted what it bought, as
 * `@/lib/local-payment` prices it.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { CheckCircle2, XCircle } from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";

import type { CreatePaymentResult } from "@intelligo-dev/billing/payment";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Spinner } from "@/components/ui/spinner";
import { CURRENCY } from "@/lib/billing-config";
import { paymentPollConfig } from "@/lib/payment-poll-config";
import { pollLocalPayment, startLocalPayment } from "@/actions/payment";

type LocalPaymentInvoice = Pick<
  CreatePaymentResult,
  "invoiceId" | "qrCode" | "deeplinks"
>;

type Step = "creating" | "waiting" | "timedOut" | "paid" | "failed";

interface LocalPaymentModalProps {
  open: boolean;
  onClose: () => void;
  /** What is being bought — a plan slug, a bundle id, an order id. */
  reference: string;
  /**
   * Amount to display, in major units of `CURRENCY` (29.5 is twenty-nine
   * and a half). The server prices the invoice itself.
   */
  amount: number;
  /** Localized name of what is being bought. */
  label: string;
  /**
   * Called once the payment is confirmed, after the server granted what
   * it bought — for closing the modal or moving on, not for granting.
   */
  onPaid: () => void;
}

export function LocalPaymentModal({
  open,
  onClose,
  reference,
  amount,
  label,
  onPaid,
}: LocalPaymentModalProps) {
  const t = useTranslations("payment-poll");
  const format = useFormatter();

  const [step, setStep] = useState<Step>("creating");
  const [invoice, setInvoice] = useState<LocalPaymentInvoice | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);

  // `onPaid` is usually an inline arrow; holding it in a ref keeps the
  // polling effect from restarting on every parent render.
  const onPaidRef = useRef(onPaid);
  onPaidRef.current = onPaid;

  const createInvoice = useCallback(async () => {
    setStep("creating");
    setError(null);
    const result = await startLocalPayment(reference);
    if (!result.success) {
      setError(result.error);
      setStep("failed");
      return;
    }
    setInvoice(result.data);
    setStep("waiting");
  }, [reference]);

  useEffect(() => {
    if (!open) return;
    void createInvoice();
  }, [open, attempt, createInvoice]);

  // One poll at a time, only while the dialog is open: closing it, or a
  // poll outliving its interval, must not run `onPaid` twice or after
  // the reader has walked away.
  useEffect(() => {
    if (!open || step !== "waiting" || !invoice) return;

    const { pollIntervalMs, timeoutMs } = paymentPollConfig;
    const startedAt = Date.now();
    let stopped = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const poll = async () => {
      if (stopped) return;
      if (Date.now() - startedAt > timeoutMs) {
        setStep("timedOut");
        return;
      }

      const result = await pollLocalPayment(invoice.invoiceId);
      if (stopped) return;
      // A failed poll is not a failed payment — the provider may just
      // be slow. Keep waiting; the timeout is the only give-up.
      if (result.success && result.data === "paid") {
        setStep("paid");
        timer = setTimeout(() => {
          if (!stopped) onPaidRef.current();
        }, 1200);
        return;
      }
      if (result.success && result.data === "failed") {
        setError(t("errors.declined"));
        setStep("failed");
        return;
      }
      timer = setTimeout(poll, pollIntervalMs);
    };
    timer = setTimeout(poll, pollIntervalMs);

    return () => {
      stopped = true;
      clearTimeout(timer);
    };
  }, [open, step, invoice, t]);

  const description =
    step === "creating"
      ? t("state.creating")
      : step === "waiting"
        ? t("state.waiting")
        : step === "timedOut"
          ? t("state.timedOut")
          : step === "paid"
            ? t("state.paid")
            : t("state.failed");

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-center">
            {t("title", {
              label,
              // The currency's own decimals: 12.50 is not 13.
              amount: format.number(amount, {
                style: "currency",
                currency: CURRENCY,
              }),
            })}
          </DialogTitle>
          <DialogDescription className="text-center">
            {description}
          </DialogDescription>
        </DialogHeader>

        <div className="flex flex-col items-center py-4">
          {step === "creating" ? (
            <Spinner className="size-8 text-primary" aria-hidden />
          ) : null}

          {step === "waiting" && invoice ? (
            <>
              {invoice.qrCode ? (
                // A plain <img>: the QR is usually a data: URI minted
                // per invoice, so there is nothing for next/image to
                // optimize, and a remote QR host would need adding to
                // next.config's remotePatterns in every consumer.
                <img
                  src={invoice.qrCode}
                  alt={t("qrAlt")}
                  width={200}
                  height={200}
                  className="mb-4 rounded-xl bg-white p-4"
                />
              ) : null}

              {invoice.deeplinks?.length ? (
                <div className="mt-2 w-full space-y-2">
                  <p className="mb-2 text-center text-xs text-muted-foreground">
                    {t("orChooseApp")}
                  </p>
                  {invoice.deeplinks.map((link) => (
                    <Button
                      key={link.url}
                      variant="outline"
                      className="w-full"
                      render={<a href={link.url} />}
                      nativeButton={false}
                    >
                      {link.app}
                    </Button>
                  ))}
                </div>
              ) : null}

              <div className="mt-4 flex items-center gap-2 text-sm text-muted-foreground">
                <Spinner className="size-3.5" aria-hidden />
                <span>{t("state.polling")}</span>
              </div>
            </>
          ) : null}

          {step === "timedOut" ? (
            <div className="space-y-3 text-center">
              <p className="text-sm text-muted-foreground">
                {t("timedOutHelp")}
              </p>
              <Button onClick={() => setAttempt((n) => n + 1)}>
                {t("retry")}
              </Button>
            </div>
          ) : null}

          {step === "paid" ? (
            <div className="text-center">
              <CheckCircle2
                className="mx-auto size-16 text-primary"
                aria-hidden
              />
              <p className="mt-4 text-lg font-semibold">{t("paidTitle")}</p>
              <p className="mt-1 text-sm text-muted-foreground">
                {t("paidBody", { label })}
              </p>
            </div>
          ) : null}

          {step === "failed" ? (
            <div className="text-center">
              <XCircle
                className="mx-auto size-16 text-destructive"
                aria-hidden
              />
              <p className="mt-4 text-lg font-semibold">{t("failedTitle")}</p>
              <p className="mt-1 text-sm text-muted-foreground">{error}</p>
              <div className="mt-4 flex justify-center gap-2">
                <Button onClick={() => setAttempt((n) => n + 1)}>
                  {t("retry")}
                </Button>
                <Button variant="outline" onClick={onClose}>
                  {t("close")}
                </Button>
              </div>
            </div>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

/**
 * A button that opens `LocalPaymentModal` for one reference and, once
 * the payment is confirmed, closes it and refreshes the page so it shows
 * what was bought.
 *
 * The pricing item's plan card renders it when `lib/plan-card-config.tsx`
 * binds it; it fits anywhere else something is sold the same way.
 */

import { useState, type ComponentProps } from "react";
import { QrCode } from "lucide-react";
import { useTranslations } from "next-intl";

import { Button } from "@/components/ui/button";
import { useRouter } from "@/i18n/navigation";

import { LocalPaymentModal } from "./local-payment-modal";

interface LocalPaymentButtonProps {
  /** What is being bought — handed to `priceLocalPayment` on the server. */
  reference: string;
  /** Amount to display, in major units of `CURRENCY`. */
  amount: number;
  /** Localized name of what is being bought. */
  label: string;
  /** The button's text; "Pay with QR" by default. */
  children?: React.ReactNode;
  variant?: ComponentProps<typeof Button>["variant"];
  className?: string;
}

export function LocalPaymentButton({
  reference,
  amount,
  label,
  children,
  variant = "outline",
  className = "w-full",
}: LocalPaymentButtonProps) {
  const t = useTranslations("payment-poll");
  const router = useRouter();
  const [open, setOpen] = useState(false);

  return (
    <>
      <Button
        variant={variant}
        className={className}
        onClick={() => setOpen(true)}
      >
        <QrCode aria-hidden />
        {children ?? t("button")}
      </Button>
      <LocalPaymentModal
        open={open}
        onClose={() => setOpen(false)}
        reference={reference}
        amount={amount}
        label={label}
        onPaid={() => {
          setOpen(false);
          router.refresh();
        }}
      />
    </>
  );
}

"use server";

/**
 * Transport for the QR-and-poll payment flow: resolve the caller's
 * workspace, ask `@/lib/local-payment` what the reference costs and
 * grants, and hand the rest to `@intelligo-dev/billing`, which records
 * the invoice and grants a paid one on the server.
 *
 * Neither action takes a user id, a workspace id or an amount from the
 * browser: who pays is a session fact, and what it costs is priced
 * server-side from `reference`.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";
import type { ActionResult } from "@intelligo-dev/next";
import {
  isBillingServiceError,
  openLocalInvoice,
  settleLocalInvoice,
  type LocalPaymentStatus,
} from "@intelligo-dev/billing";
import type { CreatePaymentResult } from "@intelligo-dev/billing/payment";

import { priceLocalPayment } from "@/lib/local-payment";

export type PaymentActionResult<T> = ActionResult<T>;

type LocalPaymentInvoice = Pick<
  CreatePaymentResult,
  "invoiceId" | "qrCode" | "deeplinks"
>;

export async function startLocalPayment(
  reference: string
): Promise<PaymentActionResult<LocalPaymentInvoice>> {
  const t = await getTranslations("payment-poll");

  if (typeof reference !== "string" || reference.length === 0) {
    return { success: false, error: t("errors.unavailable") };
  }

  let context;
  try {
    context = await requireWorkspace();
  } catch {
    return { success: false, error: t("errors.unauthorized") };
  }

  try {
    const offer = await priceLocalPayment(reference);
    if (!offer) return { success: false, error: t("errors.unavailable") };

    const invoice = await openLocalInvoice({
      workspaceId: context.workspace.id,
      userId: context.user.id,
      reference,
      price: offer.price,
      description: offer.description,
    });
    return {
      success: true,
      data: {
        invoiceId: invoice.invoiceId,
        qrCode: invoice.qrCode,
        deeplinks: invoice.deeplinks,
      },
    };
  } catch (error) {
    // Provider errors can carry account identifiers and endpoint
    // details; the caller gets the generic message, the log the cause.
    console.error("[payment-poll]", error);
    return { success: false, error: t("errors.createFailed") };
  }
}

export async function pollLocalPayment(
  invoiceId: string
): Promise<PaymentActionResult<LocalPaymentStatus>> {
  const t = await getTranslations("payment-poll");

  if (typeof invoiceId !== "string" || invoiceId.length === 0) {
    return { success: false, error: t("errors.statusFailed") };
  }

  let context;
  try {
    context = await requireWorkspace();
  } catch {
    return { success: false, error: t("errors.unauthorized") };
  }

  try {
    const status = await settleLocalInvoice({
      invoiceId,
      workspaceId: context.workspace.id,
      fulfil: async (payment) => {
        const offer = await priceLocalPayment(payment.reference);
        if (!offer) {
          throw new Error(
            `"${payment.reference}" no longer prices through lib/local-payment.ts; ` +
              `invoice ${payment.invoiceId} is paid and left unfulfilled.`
          );
        }
        return offer.grant;
      },
    });
    // What was bought shows everywhere the workspace's plan or balance
    // is rendered, so every page is stale once it lands.
    if (status === "paid") revalidatePath("/", "layout");
    return { success: true, data: status };
  } catch (error) {
    if (!isBillingServiceError(error) || error.code !== "payment_not_found") {
      console.error("[payment-poll]", error);
    }
    return { success: false, error: t("errors.statusFailed") };
  }
}

/**
 * Polling behaviour for the QR payment modal — consumer-owned.
 *
 * `pollIntervalMs`: how often to ask the provider whether the invoice
 * settled. Three seconds is a compromise: fast enough that the success
 * screen feels immediate, slow enough not to hammer a provider that
 * rate-limits status reads.
 *
 * `timeoutMs`: when to stop asking and offer a retry instead. Five
 * minutes is long enough for someone to switch apps, log into their
 * bank, and confirm — the common case that a shorter timeout would
 * cut off mid-payment.
 */

export interface PaymentPollConfig {
  pollIntervalMs: number;
  timeoutMs: number;
}

export const paymentPollConfig: PaymentPollConfig = {
  pollIntervalMs: 3_000,
  timeoutMs: 5 * 60_000,
};
